import sqlite3

import streamlit as st

import categories
import config
import database
import importers
import synthetic_data
import ui_components


def initialize(connection):
    """Prepare or upgrade demo data without replacing the existing local profile or history."""
    database.init_db(connection)
    taxonomy = categories.load_taxonomy()
    saved_version = database.get_setting(connection, 'taxonomy_version')
    if saved_version is not None and saved_version != str(taxonomy['_meta']['version']):
        st.title('Settings & About')
        st.warning('The taxonomy version has changed. Review the source files or reset demo data.')
        ui_components.render_reset_controls(connection)
        return False
    categories.seed_categories(connection, taxonomy)
    if database.get_setting(connection, 'setup_done') is None:
        with st.spinner('Preparing demo data…'):
            synthetic_data.generate_all(connection)
        st.session_state['ww_session_init_done'] = True
    synthetic_data.ensure_demo_calendar(connection)
    synthetic_data.ensure_synthetic_data(connection)
    user_id = database.get_current_user_id(connection)
    if (user_id is not None and database.get_setting(connection, 'demo_history_requested') == '1'
            and database.get_setting(connection, 'demo_history_loaded') != '1'):
        synthetic_data.create_demo_history(connection, user_id)
        synthetic_data.create_showcase_friends(connection, user_id)
        database.set_setting(connection, 'demo_history_loaded', '1')
    if not st.session_state.get('ww_session_init_done', False):
        importers.import_all(connection, taxonomy)
        database.delete_past_unconfirmed_events(connection)
        ui_components.cached_events.clear()
        st.session_state['ww_session_init_done'] = True
    return True


def main():
    """Route onboarding, Week, Rankings and Settings with recoverable errors."""
    st.set_page_config(page_title=config.APP_NAME, page_icon=':material/calendar_month:',
                       layout='wide')
    try:
        connection = ui_components.cached_connection()
        if not initialize(connection):
            return
        if st.session_state.pop('ww_rating_saved', False):
            st.toast('Thanks! Your suggestions were updated.')
        if database.get_setting(connection, 'onboarding_done') != '1':
            pages = [st.Page('views/onboarding.py', title='Welcome', default=True)]
        else:
            pages = [st.Page('views/week.py', title='Week',
                             icon=':material/calendar_view_week:', default=True),
                     st.Page('views/rankings.py', title='Rankings', icon=':material/leaderboard:'),
                     st.Page('views/settings.py', title='Settings & About',
                             icon=':material/settings:')]
        page = st.navigation(pages, position='sidebar')
        ui_components.prepare_feedback_popup(connection)
        page.run()
        ui_components.render_queued_dialog()
    except (OSError, ValueError, KeyError, sqlite3.Error):
        st.error('Could not prepare the data. Check your local source files and try again.')


if __name__ == '__main__':
    main()
